insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_108_v1'
from (values
('127.769.d.1.A',3,'A student notices that a stain on a mock evidence card turned brown after a day and asks why. This is an example of:','["asking a question based on an observation", "writing a conclusion", "buying supplies", "building a model"]'::jsonb,0,'Science begins with questions from observations.','original'),
('127.769.d.1.A',4,'Which is a testable question for a forensic lab class?','["Is forensic science cool?", "Does the type of surface change how fast a fingerprint powder sticks?", "Who is the best detective?", "Should crime be illegal?"]'::jsonb,1,'Testable questions can be answered with data.','original'),
('127.769.d.1.B',3,'A class designs a controlled test that dusts the same print on glass, plastic and wood and compares how clear each lift is. This applies scientific practices to plan a:','["fashion show", "bake sale", "comparative investigation", "field trip"]'::jsonb,2,'Comparing groups under similar conditions.','original'),
('127.769.d.1.B',4,'In a comparative lab test, the factor the students deliberately change is called the:','["dependent variable", "control group only", "constant", "independent variable"]'::jsonb,3,'Independent variable is manipulated.','original'),
('127.769.d.1.C',3,'Before pouring a chemical to develop prints, a student puts on goggles, gloves and an apron and checks the ventilation. This uses appropriate:','["safety equipment and practices", "decor choices", "music settings", "lunch breaks"]'::jsonb,0,'Wear PPE for chemicals.','original'),
('127.769.d.1.C',4,'If a chemical splashes into a student''s eyes in the lab, the first step is to:','["wipe with a paper towel", "flush the eyes at the eyewash station and alert the teacher", "wait to see if it hurts", "keep working"]'::jsonb,1,'Eyewash right away.','original'),
('127.769.d.1.D',3,'A student uses a digital scale, a calculator and a stereo microscope to measure and record fiber samples. This uses appropriate:','["office furniture", "party supplies", "tools and equipment to collect and analyze data", "props for a play"]'::jsonb,2,'Select the right tools.','original'),
('127.769.d.1.D',4,'A stereo microscope is most useful in forensics for:','["measuring temperature", "weighing liquids", "timing reactions", "viewing small trace evidence such as fibers in detail"]'::jsonb,3,'Magnifies trace evidence.','original'),
('127.769.d.1.E',3,'A student records a footprint length as 27.5 cm using a metric ruler, not in inches. This collects quantitative data using the:','["International System of Units (SI)", "random units", "Roman numeral system", "customary cooking units"]'::jsonb,0,'SI units are standard in science.','original'),
('127.769.d.1.E',4,'Which measurement is in an SI base unit?','["a mass of 9 ounces", "a mass of 0.25 kilograms", "a volume of 2 cups", "a length of 4 inches"]'::jsonb,1,'Kilogram is SI.','original'),
('127.769.d.1.F',3,'A group puts bullet-casing diameters into a table and also keeps notes on the color and condition of each casing. This organizes quantitative and qualitative data using:','["memory alone", "unlabeled scraps", "tables, graphs and descriptive notes", "loose pages"]'::jsonb,2,'Both kinds of data are organized.','original'),
('127.769.d.1.F',4,'A description such as ''rusty and scratched'' is an example of:','["a variable only", "quantitative data", "a control", "qualitative data"]'::jsonb,3,'Qualitative = descriptive.','original'),
('127.769.d.1.G',3,'A student builds a scale model of a room and places chalk marks to represent where a blood pattern was found. This develops and uses a:','["model to represent a system or phenomenon", "guess", "recipe", "perfect copy of reality"]'::jsonb,0,'Models represent systems.','original'),
('127.769.d.1.G',4,'A model of a crime scene is useful because it:','["proves guilt alone", "helps visualize and test ideas about what happened", "replaces all evidence", "eliminates doubt"]'::jsonb,1,'Models support analysis.','original'),
('127.769.d.1.H',3,'A student says her hypothesis is proved a theory after one successful test. A teacher explains that a hypothesis is a tentative explanation, while theories and laws are far better supported. This distinguishes:','["fractions, decimals and ratios", "angles, lines and arcs", "hypotheses, theories and laws", "verbs, nouns and adjectives"]'::jsonb,2,'Know the levels of scientific explanation.','original'),
('127.769.d.1.H',4,'A student says gravity is only a theory, so it is just a guess. What is wrong with this statement?','["A theory is the same thing as a hypothesis", "A theory is a guess that scientists have not yet tested", "A theory has no supporting evidence", "A scientific theory is a well-tested explanation backed by a large body of evidence"]'::jsonb,3,'Theories are well tested.','original'),
('127.769.d.2.A',3,'A crime-scene model drawn at 1:50 scale shows relative positions but not the textures and smells of the room. This identifies advantages and limitations of models such as their:','["size, scale and simplification", "name and number", "color and taste", "font and style"]'::jsonb,0,'Models simplify reality.','original'),
('127.769.d.2.A',4,'One limitation of a small-scale model of a room is that it may:','["contain more detail than reality", "leave out details of the actual environment", "never be useful", "be perfectly accurate"]'::jsonb,1,'Models omit details.','original'),
('127.769.d.2.B',3,'After recording the height of 30 bloodstain drops, a student calculates the mean and notices a pattern at higher drop heights. This analyzes data by identifying:','["recipe steps", "music genres", "significant statistical features and patterns", "handwriting styles"]'::jsonb,2,'Look for patterns in data.','original'),
('127.769.d.2.B',4,'The mean of the values 4, 6 and 8 is:','["18", "4", "8", "6"]'::jsonb,3,'(4+6+8)/3 = 6.','original'),
('127.769.d.2.C',3,'A student uses the speed of a bullet and the time to hit a target to find the distance traveled. This uses mathematical calculations to assess:','["quantitative relationships in data", "menu prices", "map colors", "spelling rules"]'::jsonb,0,'Calculations reveal relationships.','original'),
('127.769.d.2.C',4,'A bullet travels at 300 meters per second for 2 seconds. How far does it travel?','["150 meters", "600 meters", "302 meters", "1.5 meters"]'::jsonb,1,'Distance = speed × time.','original'),
('127.769.d.2.D',3,'After testing two dusting methods, a team checks whether the setup was fair and whether the design could be improved. This evaluates:','["art contests", "spelling quizzes", "experimental and engineering designs", "cooking contests"]'::jsonb,2,'Evaluate design quality.','original'),
('127.769.d.2.D',4,'A fair experimental design changes:','["every variable", "the results afterward", "no variables", "only one variable at a time"]'::jsonb,3,'Control variables.','original'),
('127.769.d.3.A',3,'After lifting prints from three surfaces, a team writes that glass held the clearest prints and backs it up with their data table and a photo. This develops explanations supported by:','["data and models", "opinion alone", "guesses", "rumors"]'::jsonb,0,'Explanations rely on evidence.','original'),
('127.769.d.3.A',4,'A strong scientific explanation should be:','["based on a feeling", "supported by evidence from the investigation", "based on popularity", "independent of data"]'::jsonb,1,'Evidence supports claims.','original'),
('127.769.d.3.B',3,'Students present their findings as a lab report alone and then discuss them in a group to refine the conclusions. This communicates explanations:','["only in secret", "only at random", "individually and collaboratively", "only silently"]'::jsonb,2,'Share and refine.','original'),
('127.769.d.3.B',4,'A good lab report should include:','["only opinions", "only photos", "only titles", "a clear claim, evidence and reasoning"]'::jsonb,3,'Claim-evidence-reasoning.','original'),
('127.769.d.3.C',3,'In a debate about whether a stain is blood, a student listens, cites test results and disagrees politely. This engages respectfully in:','["scientific argumentation", "name-calling", "quarreling", "shouting"]'::jsonb,0,'Respectful argument with evidence.','original'),
('127.769.d.3.C',4,'When a classmate challenges your conclusion, the best response is to:','["insult them", "explain your evidence and consider their point", "ignore them", "change the data"]'::jsonb,1,'Respond with evidence.','original'),
('127.769.d.4.A',3,'A student reads a forensic report and checks whether its claims follow from the evidence and whether the methods were sound. This analyzes, evaluates and critiques:','["movie scripts", "menus", "scientific explanations and solutions", "sports rules"]'::jsonb,2,'Critique explanations.','original'),
('127.769.d.4.A',4,'Critiquing a scientific claim includes asking:','["who is the author''s neighbor?", "how long is the title?", "what color is the cover?", "does the evidence really support it?"]'::jsonb,3,'Evidence check.','original'),
('127.769.d.4.B',3,'A student explains how the discovery of DNA fingerprinting changed how investigators identify suspects and what scientists thought about heredity. This relates the impact of research on:','["scientific thought and society", "weather maps", "lunch menus", "uniform colors"]'::jsonb,0,'Research changes thinking and society.','original'),
('127.769.d.4.B',4,'The development of DNA profiling in the 1980s most changed forensic science by allowing:','["faster typing", "identification of individuals from biological samples", "cheaper clothing", "brighter lights"]'::jsonb,1,'DNA identification.','original'),
('127.769.d.4.C',3,'A student visits a science museum, interviews a lab analyst and reads a journal article to learn about careers. This researches and explores:','["only video games", "only gossip", "resources such as museums, libraries and professional organizations", "only advertising"]'::jsonb,2,'Use varied resources.','original'),
('127.769.d.4.C',4,'A professional organization is a good resource for learning about forensic careers because it provides:','["sports scores", "game cheats", "party invitations", "information on training, standards and certification"]'::jsonb,3,'Professional bodies set standards.','original'),
('127.769.d.5.A',3,'A timeline starts with the first use of fingerprints for identification and ends with rapid DNA machines. This analyzes the historical development and current advancements of:','["different forensic science fields", "pottery methods", "singing styles", "gardening tools"]'::jsonb,0,'Forensics evolved over time.','original'),
('127.769.d.5.A',4,'A recent advancement in forensic science is:','["telegraph keys", "rapid DNA analysis", "the quill pen", "carbon paper"]'::jsonb,1,'Modern advance.','original'),
('127.769.d.5.B',3,'A student explains that Alphonse Bertillon''s body measurements, Edmond Locard''s exchange principle and Alec Jeffreys''s DNA fingerprinting each shaped forensics. This explains significant contributions to the:','["development of gaming", "development of cooking", "development of forensic science", "development of dance"]'::jsonb,2,'Many scientists contributed.','original'),
('127.769.d.5.B',4,'Locard''s exchange principle states that:','["only blood is evidence", "no contact leaves anything", "only prints matter", "every contact leaves a trace"]'::jsonb,3,'Contact transfers evidence.','original'),
('127.769.d.6.A',3,'A forensic analyst refuses to change a result to help a prosecutor win and reports data honestly even when it hurts the case. This summarizes the ethical standards of:','["a forensic science professional", "a chef", "a salesperson", "a racer"]'::jsonb,0,'Objectivity and honesty.','original'),
('127.769.d.6.A',4,'An ethical forensic scientist should report results that are:','["adjusted to fit a theory", "objective and based on the evidence", "kept secret", "favorable to one side"]'::jsonb,1,'Objectivity matters.','original'),
('127.769.d.6.B',3,'A student learns the terms and steps for packaging, sealing, labeling and tracking each item from a scene to the lab. This identifies terminology and procedures for:','["publishing a novel", "planning a trip", "maintaining chain of custody and evidence integrity", "running a race"]'::jsonb,2,'Procedures protect evidence integrity.','original'),
('127.769.d.6.B',4,'Evidence is usually sealed and labeled with the date, time and collector''s initials in order to:','["make it heavier", "make it pretty", "make it cheaper", "document who handled it and prevent tampering"]'::jsonb,3,'Chain of custody.','original'),
('127.769.d.6.C',3,'A class reviews the difference between a laboratory''s accreditation, standard operating procedures and quality assurance checks. This identifies terminology and procedures for:','["laboratory quality assurance and control", "parking permits", "lunch menus", "bus routes"]'::jsonb,0,'Labs use QA/QC.','original'),
('127.769.d.6.C',4,'A control sample run alongside evidence helps a lab to:','["hide errors", "confirm that the test is working correctly", "speed the test", "skip documentation"]'::jsonb,1,'Controls validate tests.','original'),
('127.769.d.6.D',3,'An analyst who expects a suspect to be guilty tends to see matches that are not really there. This researches and discusses the effect of biases such as:','["music on speech", "weather on prints", "confirmation bias on forensic results", "color on cloth"]'::jsonb,2,'Bias can distort analysis.','original'),
('127.769.d.6.D',4,'One way to reduce confirmation bias in a forensic lab is to:','["skip peer review", "let the detective choose", "tell the analyst the suspect", "have a second examiner review the results blind to the case details"]'::jsonb,3,'Blind verification.','original'),
('127.769.d.6.E',3,'A judge decides whether an expert''s methods are scientifically reliable and relevant before the jury hears the testimony. This compares the admissibility of expert testimony under:','["the Frye and Daubert standards", "school dress codes", "recess rules", "parking rules"]'::jsonb,0,'Frye and Daubert govern admissibility.','original'),
('127.769.d.6.E',4,'Under the Daubert standard, a judge considers whether a method:','["is expensive", "has been tested, peer reviewed and has a known error rate", "is old", "is popular"]'::jsonb,1,'Daubert factors.','original'),
('127.769.d.7.A',3,'A student researches the degrees, certifications and lab experience required to become a DNA analyst or a toxicologist. This explores:','["sports leagues", "hair salons", "discipline-specific requirements for careers in forensic science", "hobby clubs"]'::jsonb,2,'Careers have specific requirements.','original'),
('127.769.d.7.A',4,'Most forensic analyst jobs require at least a:','["driver''s permit only", "fashion portfolio", "music audition", "bachelor''s degree in a natural science"]'::jsonb,3,'Science degree is typical.','original'),
('127.769.d.7.B',3,'Students compare what a crime scene investigator, a lab analyst, a medical examiner and a forensic attorney do. This differentiates:','["the roles and responsibilities of professionals in the criminal justice system", "recipes of cooks", "tasks of farmers", "jobs of pilots"]'::jsonb,0,'Roles differ.','original'),
('127.769.d.7.B',4,'The professional who investigates deaths and determines cause and manner of death is the:','["court clerk", "medical examiner or coroner", "juror", "bailiff"]'::jsonb,1,'Death investigations.','original'),
('127.769.d.7.C',3,'A chart shows toxicology testing fluids for drugs, trace analysis examining fibers and digital forensics recovering files. This differentiates the functions of:','["sports teams", "art classes", "various forensic science disciplines", "music bands"]'::jsonb,2,'Disciplines specialize.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_108_v1'
from (values
('127.769.d.7.C',4,'A discipline that analyzes bodily fluids for drugs and poisons is:','["document examination", "ballistics", "entomology", "toxicology"]'::jsonb,3,'Toxicology analyzes substances in fluids.','original'),
('127.769.d.8.A',3,'At a crime scene, one person photographs, one sketches, one collects evidence and one keeps the log. This explains the roles and tasks needed to complete:','["a crime scene examination", "a movie shoot", "a cooking class", "a school play"]'::jsonb,0,'Teams divide scene tasks.','original'),
('127.769.d.8.A',4,'The person who logs everyone entering and leaving the scene is the:','["witness", "scene recorder or entry log officer", "defendant", "jury foreman"]'::jsonb,1,'Scene access log.','original'),
('127.769.d.8.B',3,'An examiner writes her observations in order, with exact measurements and no guesses, so another investigator could use them months later. This develops a detailed, technical:','["opinion column", "poem", "written record based on observations and facts", "fiction story"]'::jsonb,2,'Technical notes record facts.','original'),
('127.769.d.8.B',4,'In crime-scene notes, it is best to record:','["gossip", "jokes", "assumptions", "facts that were observed and measured"]'::jsonb,3,'Objective notes.','original'),
('127.769.d.8.C',3,'A student explains why officers generally need a warrant or consent, and how the plain-view exception works before searching a home. This discusses elements of criminal law that guide:','["search and seizure of evidence", "traffic reports", "menu design", "school registration"]'::jsonb,0,'Fourth Amendment limits searches.','original'),
('127.769.d.8.C',4,'A warrant must be supported by:','["a guess", "probable cause", "an anonymous rumor", "a hunch"]'::jsonb,1,'Probable cause is required.','original'),
('127.769.d.8.D',3,'A team first walks a simulated scene along a grid, then makes a second pass in the opposite direction to catch what was missed. This conducts:','["a single glance", "a quick skim", "a primary and secondary systematic search", "a random wander"]'::jsonb,2,'Second pass catches misses.','original'),
('127.769.d.8.D',4,'A common systematic search pattern for a large outdoor scene is the:','["speed search", "guess search", "random search", "grid or lane search"]'::jsonb,3,'Grid search pattern.','original'),
('127.769.d.8.E',3,'A technician takes overall, midrange and close-up photographs with a scale in the frame before moving anything. This documents a scene using:','["photographic or audiovisual equipment", "handwritten letters", "sound effects", "poster boards"]'::jsonb,0,'Photography records the scene.','original'),
('127.769.d.8.E',4,'A scale placed next to an object in a scene photograph allows:','["time tracking", "accurate measurement from the picture", "noise reduction", "color matching"]'::jsonb,1,'Scales give size.','original'),
('127.769.d.8.F',3,'A student draws a room layout using a measuring tape and coordinates from two fixed points to mark where each item lay. This generates a:','["cartoon", "menu board", "crime scene sketch including coordinates", "family tree"]'::jsonb,2,'Sketches use measurements.','original'),
('127.769.d.8.F',4,'In a triangulation sketch, an item''s position is recorded by measuring its distance from:','["a witness''s guess", "one moving object", "no reference", "two fixed reference points"]'::jsonb,3,'Triangulation uses fixed points.','original'),
('127.769.d.8.G',3,'An investigator places a bloody shirt in a paper bag, seals it, labels it and keeps it dry to prevent mold. This demonstrates proper techniques for:','["collecting, packaging and preserving evidence", "exposing evidence", "tossing evidence", "mixing evidence"]'::jsonb,0,'Paper bags protect biological items.','original'),
('127.769.d.8.G',4,'Wet biological evidence should be packaged in a:','["glass jar", "paper container so it can breathe", "metal can", "plastic bag sealed tight"]'::jsonb,1,'Plastic traps moisture.','original'),
('127.769.d.9.A',3,'A student sorts a set of prints into those with concentric circles, those with a ridge that enters and exits on the same side, and those with a gentle wave shape. This compares the three major fingerprint patterns:','["stars, hearts and moons", "spirals, dots and dashes", "arches, loops and whorls", "squares, rectangles and circles"]'::jsonb,2,'Three basic patterns.','original'),
('127.769.d.9.A',4,'An examiner reviewing a stack of ten-print cards finds that most fingers show a ridge that enters and exits on the same side. Which pattern is this?','["tented arch only", "whorl", "arch", "loop"]'::jsonb,3,'Loops are the most frequent pattern.','original'),
('127.769.d.9.B',3,'An examiner marks places where a ridge splits in two, where it ends abruptly and where a tiny ridge sits alone. This identifies the minutiae including:','["bifurcations, ridge endings and islands", "freckles, moles and veins", "thumbs, palms and wrists", "arches, whorls and loops only"]'::jsonb,0,'Minutiae are ridge details.','original'),
('127.769.d.9.B',4,'A ridge that splits into two branches is called a:','["island", "bifurcation", "delta", "ridge ending"]'::jsonb,1,'Bifurcation = fork.','original'),
('127.769.d.9.C',3,'A print left in wet paint can be seen and felt, one in dust is visible, and one on glass from skin oils needs development. This distinguishes:','["red, blue and green marks", "open, closed and locked prints", "patent, plastic and latent impressions", "sticky, shiny and dull coats"]'::jsonb,2,'Print types differ in visibility.','original'),
('127.769.d.9.C',4,'A fingerprint left in soft wax or putty is a:','["patent print", "chemical print", "latent print", "plastic print"]'::jsonb,3,'Plastic prints are 3D impressions.','original'),
('127.769.d.9.D',3,'A student brushes powder on a smooth glass slide and lifts the print with clear tape onto a card. This performs development and lifting of latent prints on:','["nonporous surfaces", "skin only", "porous paper only", "water"]'::jsonb,0,'Powder works on smooth surfaces.','original'),
('127.769.d.9.D',4,'Fingerprint powder works best on:','["unfinished wood", "smooth, nonporous surfaces such as glass", "wet sand", "rough fabric"]'::jsonb,1,'Nonporous surfaces hold residue on top.','original'),
('127.769.d.9.E',3,'On a sheet of paper, a technician uses a solution that reacts with amino acids in sweat and turns the print purple. This develops latent prints using:','["oil paint", "fingerprint powder", "chemical processes such as ninhydrin", "chalk"]'::jsonb,2,'Ninhydrin reacts with amino acids.','original'),
('127.769.d.9.E',4,'Cyanoacrylate (super glue) fuming is used to develop prints on:','["water", "fabric only", "porous paper only", "nonporous items such as plastic and metal"]'::jsonb,3,'Fuming builds a white polymer.','original'),
('127.769.d.9.F',3,'A latent print from a scene is scanned and compared with millions of stored records to find possible matches. This explains the:','["Integrated Automated Fingerprint Identification System (IAFIS)", "Island fishing system", "Internet music system", "Insurance filing system"]'::jsonb,0,'IAFIS is the national fingerprint database.','original'),
('127.769.d.9.F',4,'After a database returns candidate matches for a print, a trained examiner must:','["accept it without review", "verify the match by direct comparison", "ignore the list", "delete the print"]'::jsonb,1,'Human verification is needed.','original'),
('127.769.d.10.A',3,'An examiner notes that a pry bar''s width matches a groove in a door frame, but tiny nicks inside the groove vary from tool to tool. This analyzes the class and individual characteristics of:','["hair strands", "blood spatters", "tool mark impressions", "tire tracks only"]'::jsonb,2,'Class = shape; individual = wear nicks.','original'),
('127.769.d.10.A',4,'A screwdriver''s blade width is an example of a:','["random event", "individual characteristic", "contaminant", "class characteristic"]'::jsonb,3,'Class characteristics are shared by a group.','original'),
('127.769.d.10.B',3,'A shoe print at a scene shows the same sole pattern as a suspect''s shoe, plus a unique cut across the heel. This analyzes class and individual characteristics of:','["footwear impressions", "fingerprints", "tool marks", "tire impressions"]'::jsonb,0,'Wear and damage make shoes unique.','original'),
('127.769.d.10.B',4,'A cut or nick that appears only on one shoe sole is an:','["class characteristic", "individual characteristic", "brand name", "manufacturing design"]'::jsonb,1,'Acquired damage is individual.','original'),
('127.769.d.10.C',3,'A cast of a tire track shows the tread design and brand but also a unique gouge from a nail. This analyzes class and individual characteristics of:','["footwear impressions", "glass fractures", "tire tread impressions", "hair"]'::jsonb,2,'Tread design is class; gouge is individual.','original'),
('127.769.d.10.C',4,'The tread pattern of a tire that is common to many tires of one model is a:','["DNA marker", "individual characteristic", "fingerprint ridge", "class characteristic"]'::jsonb,3,'Pattern is a class trait.','original'),
('127.769.d.10.D',3,'A student pours casting material into a track at a mock scene and later compares it with test impressions of a suspect''s shoes. This compares:','["impression evidence with known exemplars", "recipes with menus", "maps with legends", "graphs with labels"]'::jsonb,0,'Exemplars are known samples for comparison.','original'),
('127.769.d.10.D',4,'A known sample used for comparison with evidence is called an:','["outlier", "exemplar", "contaminant", "artifact"]'::jsonb,1,'Exemplars come from known sources.','original'),
('127.769.d.11.A',3,'At a mock scene, a technician uses tweezers and tape lifts to gather strands from a victim''s clothing and places each in a separate fold. This demonstrates how to collect:','["glass shards", "gunshot residue", "hair and fiber evidence", "blood spatter"]'::jsonb,2,'Trace evidence is collected carefully.','original'),
('127.769.d.11.A',4,'Each hair or fiber item should be packaged:','["taped on a wall", "loosely in a pocket", "together in one bag", "separately to prevent cross-contamination"]'::jsonb,3,'Separate packaging.','original'),
('127.769.d.11.B',3,'A lab technician views a strand on a comparison microscope next to a known sample and notes color, scale pattern and thickness. This performs:','["analysis of hair and fiber evidence using forensic science procedures", "a driving test", "a typing test", "a taste test"]'::jsonb,0,'Microscopy compares traits.','original'),
('127.769.d.11.B',4,'A comparison microscope allows an examiner to:','["print samples", "view two samples side by side", "freeze samples", "dissolve samples"]'::jsonb,1,'Side-by-side comparison.','original'),
('127.769.d.11.C',3,'Under magnification, a human hair shows a thin medulla while a cat hair shows a wide, ladder-like one. This compares the microscopic characteristics of:','["glass and plastic", "paper and cloth", "human hair and non-human hair", "blood and saliva"]'::jsonb,2,'Medulla patterns differ by species.','original'),
('127.769.d.11.C',4,'The center core of a hair shaft is the:','["cuticle", "cortex", "root bulb", "medulla"]'::jsonb,3,'Medulla is the central canal.','original'),
('127.769.d.11.D',3,'A student labels a diagram of a single strand showing the outer scales, the middle layer with pigment and the central canal. This describes and illustrates the microscopic characteristics of:','["hair", "glass", "soil", "paint"]'::jsonb,0,'Cuticle, cortex and medulla.','original'),
('127.769.d.11.D',4,'The outer layer of a hair, made of overlapping scales, is the:','["cortex", "cuticle", "follicle", "medulla"]'::jsonb,1,'Cuticle = outer scale layer.','original'),
('127.769.d.11.E',3,'A technician burns a small thread: one smells like burning hair and turns to ash, and another melts into a hard bead. This differentiates between:','["metal and wood", "paint and ink", "natural and synthetic fibers", "glass and plastic"]'::jsonb,2,'Burn tests help classify fibers.','original'),
('127.769.d.11.E',4,'Cotton and wool are examples of:','["glass fibers", "metal fibers", "synthetic fibers", "natural fibers"]'::jsonb,3,'Plant and animal fibers.','original'),
('127.769.d.12.A',3,'At a mock scene with a broken window, a technician collects shards from the inside and outside surfaces into separate containers. This demonstrates how to collect and preserve:','["glass evidence", "blood stains", "paint chips", "soil layers"]'::jsonb,0,'Glass is collected carefully.','original'),
('127.769.d.12.A',4,'Glass fragments should be packaged in:','["paper towels", "rigid, sealed containers to protect them", "envelopes only", "open plastic bags"]'::jsonb,1,'Prevent breakage and loss.','original'),
('127.769.d.12.B',3,'Students compare window glass, tempered car glass and heat-resistant lab glass by melting behavior and breaking pattern. This compares the composition of:','["wood and plastic", "paper and cloth", "various types of glass such as soda lime and borosilicate", "metal and rubber"]'::jsonb,2,'Glass types differ in composition.','original'),
('127.769.d.12.B',4,'Borosilicate glass is known for its:','["softness", "ability to bounce", "color change", "resistance to heat"]'::jsonb,3,'Used in lab glassware.','original'),
('127.769.d.12.C',3,'On a broken window, a technician examines the rib marks on the edge of the radial cracks and the sides of the concentric cracks to learn where the object struck from. This determines:','["the direction of a projectile by examining glass fractures", "the shape of the frame", "the age of the glass", "the color of the glass"]'::jsonb,0,'Fracture patterns indicate direction.','original'),
('127.769.d.12.C',4,'In a bullet hole in glass, the crater (cone) widens on the side:','["at the bottom", "where the projectile exits", "at the top", "where the projectile enters"]'::jsonb,1,'Exit side is cratered.','original'),
('127.769.d.12.D',3,'A lab places a glass fragment in oil and heats it until it seems to vanish, then records the temperature to compare with another fragment. This defines and uses the:','["boiling point of oil", "weight of paper", "refractive index of glass", "density of wood"]'::jsonb,2,'Refractive index is a bending-of-light measure.','original'),
('127.769.d.12.D',4,'Refractive index describes how much a material:','["reflects sound", "absorbs water", "conducts heat", "bends light"]'::jsonb,3,'Light bending.','original'),
('127.769.d.13.A',3,'A forensic examiner studies ink, paper and printing to decide whether a contract was altered after signing. This researches the different types of examinations performed on:','["questioned documents", "bite marks", "blood patterns", "tire tracks"]'::jsonb,0,'Document examination.','original'),
('127.769.d.13.A',4,'One thing a document examiner may test is whether:','["a paper is soft", "two inks are chemically different", "a pen is expensive", "a signer is happy"]'::jsonb,1,'Ink differentiation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_108_v1'
from (values
('127.769.d.13.B',3,'A teller shines ultraviolet light on a bill to see a hidden strip, and checks for a watermark and color-shifting ink. This investigates security features of:','["library cards", "movie tickets", "U.S. and foreign currency", "bus passes"]'::jsonb,2,'Currency has security features.','original'),
('127.769.d.13.B',4,'A faint image seen when a bill is held up to light is a:','["bank stamp", "mint seal", "serial stamp", "watermark"]'::jsonb,3,'Watermark security feature.','original'),
('127.769.d.13.C',3,'An examiner compares an unknown note with known writing samples by looking at slant, spacing and letter forms. This performs:','["handwriting comparisons with exemplars", "soil testing", "DNA profiling", "fingerprint dusting"]'::jsonb,0,'Handwriting characteristics are compared.','original'),
('127.769.d.13.C',4,'A good handwriting exemplar is one that:','["is scribbled quickly", "is written naturally by the suspect under similar conditions", "is copied from the note", "is traced"]'::jsonb,1,'Natural writing is best.','original'),
('127.769.d.14.A',3,'A student takes apart a model of a pistol and a rifle to show the barrel, hammer or firing pin, and trigger. This describes the mechanism of modern firearms such as:','["bows and arrows", "swords and shields", "long guns and handguns", "clubs and spears"]'::jsonb,2,'Firearms share basic parts.','original'),
('127.769.d.14.A',4,'In a firearm, the part that strikes the primer to ignite the cartridge is the:','["magazine spring", "sight", "trigger guard", "firing pin"]'::jsonb,3,'Firing pin initiates ignition.','original'),
('127.769.d.14.B',3,'An examiner looks at the striations on a bullet and the marks left on a cartridge case to learn about the gun that fired it. This identifies components and characteristics of:','["bullet and cartridge casings", "glass and plastic", "paper and cloth", "wood and metal"]'::jsonb,0,'Marks reveal the gun used.','original'),
('127.769.d.14.B',4,'Spiral grooves inside a gun barrel leave marks on a bullet called:','["scorch marks", "rifling marks or striations", "watermarks", "fingerprints"]'::jsonb,1,'Rifling marks.','original'),
('127.769.d.14.C',3,'A swab from a suspect''s hand is tested for tiny particles of lead, barium and antimony. This describes the composition and method of analysis for:','["glass dust", "soil grains", "gunshot residue", "paint flakes"]'::jsonb,2,'GSR contains characteristic elements.','original'),
('127.769.d.14.C',4,'Gunshot residue particles are most often identified using a:','["thermometer", "kitchen scale", "ruler", "scanning electron microscope with elemental analysis"]'::jsonb,3,'SEM-EDS is standard.','original'),
('127.769.d.14.D',3,'Using strings and a protractor at a mock scene, students line up two bullet holes to estimate where a shot came from. This conducts and calculates:','["trajectory analysis of bullet strikes", "recipe scaling", "time zones", "map scaling"]'::jsonb,0,'String and angle show path.','original'),
('127.769.d.14.D',4,'Investigators use string to show the path of a bullet because a bullet''s path is nearly a:','["circle", "straight line over short distances", "zigzag", "spiral"]'::jsonb,1,'Short-range paths are straight.','original'),
('127.769.d.14.E',3,'A detective wants to learn whether a gun used in one shooting is tied to casings found at other crime scenes in different cities. This identifies the type of information available through the:','["National Weather Service", "National Park Service", "National Integrated Ballistic Information Network (NIBIN)", "National Library"]'::jsonb,2,'NIBIN links ballistic evidence.','original'),
('127.769.d.14.E',4,'Two unconnected shootings in different counties turn up casings fired from the same weapon. Which resource would most likely reveal that link?','["a postal tracking system", "a weather service", "a fingerprint database only", "the national ballistic imaging network, NIBIN"]'::jsonb,3,'NIBIN correlates casing images across cases.','original'),
('127.769.d.15.A',3,'A student explains that one lab measures drug levels in blood to see impairment, while another identifies a powder as an illegal drug. This differentiates between:','["toxicological analysis and controlled substance analysis", "spelling and grammar", "addition and subtraction", "history and geography"]'::jsonb,0,'Different questions, different analyses.','original'),
('127.769.d.15.A',4,'Toxicology typically focuses on:','["handwriting", "drugs and poisons in bodily samples", "tire tracks", "tool marks"]'::jsonb,1,'Toxicology = body fluids/tissues.','original'),
('127.769.d.15.B',3,'A chart sorts drugs by medical use and risk of abuse into Schedule I through V. This classifies controlled substances under:','["the tax code", "the fire code", "the Controlled Substances Act schedules", "the zoning code"]'::jsonb,2,'Schedules rank by use and abuse potential.','original'),
('127.769.d.15.B',4,'Schedule I substances are defined as having:','["no regulation", "low abuse potential", "accepted medical use", "high abuse potential and no accepted medical use"]'::jsonb,3,'Schedule I definition.','original'),
('127.769.d.15.C',3,'A technician first runs a quick color test on an unknown powder and then confirms its identity using an instrument that separates and identifies compounds. This identifies unknowns using:','["presumptive and confirmatory procedures", "taste and smell", "guessing and checking", "luck and chance"]'::jsonb,0,'Quick screen then confirm.','original'),
('127.769.d.15.C',4,'A presumptive test is one that:','["is never used", "gives a quick, preliminary indication", "proves identity beyond doubt", "replaces confirmation"]'::jsonb,1,'Needs confirmation.','original'),
('127.769.d.16.A',3,'A toxicologist explains how a drug enters blood, spreads to organs, is broken down by the liver and leaves through urine. This explains:','["jumping, running and kicking", "reading, writing and speaking", "absorption, distribution, metabolism and elimination", "sorting, filing and shipping"]'::jsonb,2,'ADME describes drug processing.','original'),
('127.769.d.16.A',4,'The liver mainly handles which step of drug processing?','["elimination only", "distribution", "absorption", "metabolism"]'::jsonb,3,'Liver metabolizes drugs.','original'),
('127.769.d.16.B',3,'A lab screens a blood sample with an immunoassay and then confirms any positives using mass spectrometry. This describes presumptive and confirmatory procedures as they relate to:','["toxicology", "document analysis", "fiber analysis", "firearm analysis"]'::jsonb,0,'Screen then confirm.','original'),
('127.769.d.16.B',4,'Gas chromatography-mass spectrometry is commonly used as a:','["presumptive test", "confirmatory test", "taste test", "field test"]'::jsonb,1,'GC-MS confirms identity.','original'),
('127.769.d.16.C',3,'An analyst reads a chart showing a blood alcohol level of 0.10 and compares it with the legal limit of 0.08. This interprets:','["menus", "maps", "results from presumptive and confirmatory procedures", "plays"]'::jsonb,2,'Interpret numerical results.','original'),
('127.769.d.16.C',4,'A blood alcohol concentration above the legal limit of 0.08 means a driver is:','["exempt", "sober by law", "under the limit", "over the legal limit"]'::jsonb,3,'0.10 exceeds 0.08.','original'),
('127.769.d.16.D',3,'Before testing, a lab technician wears gloves, cleans the bench and uses a new pipette tip for each sample. This explains the precautions necessary for:','["proper handling of toxicological samples and avoiding contamination", "playing games", "decorating a room", "storing food"]'::jsonb,0,'Contamination control.','original'),
('127.769.d.16.D',4,'Using a clean tool for every sample prevents:','["evaporation", "cross-contamination", "labeling", "freezing"]'::jsonb,1,'Avoid mixing samples.','original'),
('127.769.d.17.A',3,'A blood drop that hits a smooth tile looks round, while one that hits rough wood spreads with irregular edges. This analyzes blood stain patterns based on:','["music type", "paint color", "surface type and appearance", "room size"]'::jsonb,2,'Surface affects pattern.','original'),
('127.769.d.17.A',4,'A long, narrow bloodstain with a pointed tail suggests a drop that:','["was wiped", "was dried", "fell straight down", "hit the surface at a low angle"]'::jsonb,3,'Elongated stain indicates an angle.','original'),
('127.769.d.17.B',3,'On a floor that has been cleaned, a technician sprays a reagent that glows to reveal traces of blood. This explains the methods of:','["chemically enhancing latent blood patterns using luminol", "painting surfaces", "testing fibers", "cleaning fingerprints"]'::jsonb,0,'Luminol reveals hidden blood.','original'),
('127.769.d.17.B',4,'Luminol is used at a scene to:','["identify gunshot residue", "reveal latent blood stains", "find fibers", "measure glass"]'::jsonb,1,'Luminol chemiluminescence.','original'),
('127.769.d.17.C',3,'A technician rubs a swab on a stain and adds a reagent that changes color if blood might be present. This conducts and interprets:','["fingerprint tests", "tire tests", "blood presumptive tests", "handwriting tests"]'::jsonb,2,'Presumptive tests indicate possible blood.','original'),
('127.769.d.17.C',4,'A positive presumptive test for blood means that:','["the stain is old", "the suspect is guilty", "blood is definitely human", "blood may be present and further testing is needed"]'::jsonb,3,'Presumptive needs confirmation.','original'),
('127.769.d.18.A',3,'A student labels samples of blood, saliva, hair with root and skin cells and uses clean gloves and swabs for each one. This identifies types of biological samples and practices proper:','["collection techniques", "sharing tools", "storage in sunlight", "skipping labels"]'::jsonb,0,'Proper collection avoids contamination.','original'),
('127.769.d.18.A',4,'Biological samples are usually dried before packaging to:','["increase weight", "prevent mold and degradation", "change color", "add moisture"]'::jsonb,1,'Dryness preserves DNA.','original'),
('127.769.d.18.B',3,'A student explains that type A blood has A antigens on red cells and anti-B antibodies in plasma. This identifies red blood cell:','["hairs and fibers", "tools and tires", "antigens and antibodies relating to blood typing", "bones and joints"]'::jsonb,2,'ABO system.','original'),
('127.769.d.18.B',4,'A person with type O blood has red cells that carry:','["a mix of A and B antigens", "only the B antigen", "only the A antigen", "no A or B antigens"]'::jsonb,3,'Type O has no A or B antigens.','original'),
('127.769.d.18.C',3,'A model of a twisted ladder with sugar-phosphate rails and base-pair rungs represents a:','["DNA molecule", "starch grain", "protein chain", "fat molecule"]'::jsonb,0,'Double helix.','original'),
('127.769.d.18.C',4,'In DNA, adenine pairs with:','["guanine", "thymine", "cytosine", "uracil"]'::jsonb,1,'A pairs with T.','original'),
('127.769.d.18.D',3,'A lab extracts DNA, copies targeted regions by PCR and separates the fragments to create a profile. This explains the analytical procedure of:','["building a model plane", "editing a video", "generating a DNA profile", "baking bread"]'::jsonb,2,'Extract, amplify, separate.','original'),
('127.769.d.18.D',4,'The step in which specific DNA regions are copied many times is:','["freezing", "staining", "centrifugation", "polymerase chain reaction (PCR)"]'::jsonb,3,'PCR amplifies DNA.','original'),
('127.769.d.18.E',3,'Besides nuclear DNA, a lab may test mitochondrial DNA from old hair shafts and Y-STR markers to track male lineage. This explains the different methodologies for:','["types of DNA testing", "types of fibers", "types of glass", "types of tires"]'::jsonb,0,'Different tests suit different samples.','original'),
('127.769.d.18.E',4,'Mitochondrial DNA is inherited from the:','["neither", "mother", "both parents equally", "father"]'::jsonb,1,'Maternal inheritance.','original'),
('127.769.d.18.F',3,'A graph of peaks shows allele positions at each location in a DNA sample, with two peaks at heterozygous sites. This interprets the components of an:','["compass", "thermometer", "electropherogram", "barometer"]'::jsonb,2,'Peaks are alleles.','original'),
('127.769.d.18.F',4,'In an electropherogram, a single tall peak at a location often means the person is:','["absent", "heterozygous", "contaminated", "homozygous at that location"]'::jsonb,3,'One allele type.','original'),
('127.769.d.18.G',3,'Investigators upload a profile to a national database that links offenders, arrestees and crime-scene samples. This explores DNA databasing systems such as:','["the Combined DNA Index System (CODIS)", "the Central Menu System", "the Common Reading System", "the Combined Weather System"]'::jsonb,0,'CODIS links DNA profiles.','original'),
('127.769.d.18.G',4,'A ''cold hit'' in a DNA database occurs when:','["no match is found", "a crime-scene profile matches a profile with no previous suspect", "a sample is lost", "a profile is deleted"]'::jsonb,1,'Cold hit links to unknown suspects.','original'),
('127.769.d.19.A',3,'Rigor mortis stiffens a body, algor mortis cools it and livor mortis causes purple pooling of blood in low areas. This explains the principles used to estimate:','["the cause of a fire", "the age of a tire", "the time since death", "the weight of a bullet"]'::jsonb,2,'Postmortem changes aid time estimates.','original'),
('127.769.d.19.A',4,'The pooling of blood in the lowest parts of a body after death is called:','["algor mortis", "autolysis only", "rigor mortis", "livor mortis"]'::jsonb,3,'Livor = lividity.','original'),
('127.769.d.19.B',3,'A medical examiner notes jagged tears with bridging tissue and distinguishes them from clean cuts with smooth edges. This differentiates between types of:','["wound patterns such as lacerations and incised wounds", "fiber types", "glass types", "paper types"]'::jsonb,0,'Wound edges reveal mechanism.','original'),
('127.769.d.19.B',4,'A wound with ragged, irregular edges caused by blunt force is called a:','["puncture only", "laceration", "incision", "burn"]'::jsonb,1,'Lacerations are tears.','original'),
('127.769.d.19.C',3,'A student reads an autopsy report that lists injuries, organ findings and toxicology to decide how and why a person died. This determines the:','["speed of a car", "cost of a trial", "cause and manner of death", "age of a building"]'::jsonb,2,'Autopsy determines cause and manner.','original'),
('127.769.d.19.C',4,'The manner of death can be classified as natural, accident, suicide, homicide or:','["unknown only", "lost", "random", "undetermined"]'::jsonb,3,'Undetermined is a category.','original'),
('127.769.d.19.D',3,'Entomologists study which insects colonize a body and their stages of development to estimate how long ago a person died. This determines time of death using:','["entomology", "botany", "geology", "astronomy"]'::jsonb,0,'Insect succession indicates time.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
